import {test} from 'node:test';
import assert from 'node:assert/strict';
import {applyCoupon} from '../src/coupon.mjs';

test('hidden check', async () => {
  assert.equal(applyCoupon(12345, 'WELCOME10'), 11110);
  assert.equal(applyCoupon(10000, 'FLAT3000'), 7000);
  assert.equal(applyCoupon(2000, 'FLAT3000'), 0);
  assert.throws(() => applyCoupon(1000, 'NOPE'), /unknown_coupon/);
});
